import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"8.3 铭牌与接线方式","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-3-ming-pai-yu-jie-xian-fang-shi.md","filePath":"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-3-ming-pai-yu-jie-xian-fang-shi.md","lastUpdated":1793095197000}'),n={name:"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-3-ming-pai-yu-jie-xian-fang-shi.md"};function l(e,t,s,d,g,h){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="_8-3-铭牌与接线方式" tabindex="-1">8.3 铭牌与接线方式 <a class="header-anchor" href="#_8-3-铭牌与接线方式" aria-label="Permalink to &quot;8.3 铭牌与接线方式&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>每台电动机上都有一块&quot;身份证&quot;——<strong>铭牌</strong>,写清了它该用多少伏、怎么接。这一节看懂铭牌参数,并掌握<strong>星形(Y)和三角形(△)两种接法</strong>怎么选。接错了,轻则转不起来,重则烧电机。</p><h2 id="一、看懂电动机铭牌" tabindex="-1">一、看懂电动机铭牌 <a class="header-anchor" href="#一、看懂电动机铭牌" aria-label="Permalink to &quot;一、看懂电动机铭牌&quot;">​</a></h2><p>铭牌上的主要参数:</p><table tabindex="0"><thead><tr><th>参数</th><th>含义</th></tr></thead><tbody><tr><td><strong>额定电压</strong></td><td>正常工作的电源电压(如 380 V)</td></tr><tr><td><strong>额定电流</strong></td><td>正常负载下的线电流</td></tr><tr><td><strong>额定功率</strong></td><td>输出机械功率(kW)</td></tr><tr><td><strong>额定转速</strong></td><td>正常负载下的转子转速(r/min)</td></tr><tr><td><strong>接法</strong></td><td>Y(星形)或 △(三角形)</td></tr><tr><td><strong>绝缘等级</strong></td><td>绝缘耐热等级(如 B、F 级)</td></tr><tr><td><strong>频率</strong></td><td>电源频率(50 Hz)</td></tr></tbody></table><blockquote><p>💡 <strong>额定值</strong>就是&quot;正常情况&quot;的值——电压、电流、功率都要按铭牌来,超了叫过载,低了叫欠压,都会出问题。</p></blockquote><h2 id="二、y-接法与-△-接法" tabindex="-1">二、Y 接法与 △ 接法 <a class="header-anchor" href="#二、y-接法与-△-接法" aria-label="Permalink to &quot;二、Y 接法与 △ 接法&quot;">​</a></h2><p>电动机接线盒里有六个接线端子:<code>U1 U2、V1 V2、W1 W2</code>。</p><h3 id="星形-y-接法" tabindex="-1">星形(Y)接法 <a class="header-anchor" href="#星形-y-接法" aria-label="Permalink to &quot;星形(Y)接法&quot;">​</a></h3><p>三个绕组的末端(U2、V2、W2)<strong>连在一起</strong>形成中性点,首端(U1、V1、W1)接三相电源:</p><ul><li>每个绕组承受的是<strong>相电压</strong>(220 V);</li><li>绕组电压低,电流小,发热小。</li></ul><h3 id="三角形-△-接法" tabindex="-1">三角形(△)接法 <a class="header-anchor" href="#三角形-△-接法" aria-label="Permalink to &quot;三角形(△)接法&quot;">​</a></h3><p>每个绕组的<strong>首尾相连</strong>成闭合三角形,三个连接点接三相电源:</p><ul><li>每个绕组承受的是<strong>线电压</strong>(380 V);</li><li>绕组电压高,输出功率大。</li></ul><h2 id="三、接法由铭牌决定-必考" tabindex="-1">三、接法由铭牌决定(必考) <a class="header-anchor" href="#三、接法由铭牌决定-必考" aria-label="Permalink to &quot;三、接法由铭牌决定(必考)&quot;">​</a></h2><p>电动机铭牌上会写明接法,常见两种情况:</p><table tabindex="0"><thead><tr><th>铭牌标注</th><th>说明</th></tr></thead><tbody><tr><td><strong>380 V / △ 接法</strong></td><td>三相 380 V 电源下,用<strong>三角形接法</strong>(绕组承受 380 V)</td></tr><tr><td><strong>380 V / Y 接法</strong></td><td>三相 380 V 电源下,用<strong>星形接法</strong>(绕组承受 220 V)</td></tr><tr><td><strong>380V / △、220V / Y</strong></td><td>双电压电机:380 V 用 △,220 V 用 Y</td></tr></tbody></table><blockquote><p>⚠️ 判断题高频:<strong>铭牌标 △ 接法的电动机,若误接成 Y 接法,绕组电压不足,输出功率下降、转不动</strong>;<strong>铭牌标 Y 接法的电动机误接成 △,绕组电压过高(380 V),会烧毁电动机</strong>。接法不能随意换!</p></blockquote><h2 id="四、接线注意事项" tabindex="-1">四、接线注意事项 <a class="header-anchor" href="#四、接线注意事项" aria-label="Permalink to &quot;四、接线注意事项&quot;">​</a></h2><ul><li>接线前<strong>核对铭牌接法</strong>,确认电源电压;</li><li>接线盒内端子要<strong>对号入座</strong>,三相别接反(接反则反转);</li><li>电动机金属外壳<strong>必须可靠接地(保护接地)</strong>,防止漏电触电;</li><li>接线处要压紧、绝缘良好。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 铭牌<strong>接法决定怎么接线</strong>:标 Y 用星形,标 △ 用三角形,不能随意换。</li><li>✅ 双电压电机:380 V 用 △、220 V 用 Y。</li><li>✅ 接线端子:U1U2、V1V2、W1W2。</li><li>✅ 电动机外壳必须<strong>保护接地</strong>。</li><li>⚠️ 易混点:Y 误接 △ 会烧电机(电压过高);△ 误接 Y 会转不动(电压不足)。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>铭牌是电动机的&quot;身份证&quot;,接法、电压、电流都要按它来。</li><li>星形绕组承相电压,三角形绕组承线电压。</li><li>接法错了要么烧电机、要么转不动,必须严格按铭牌。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)铭牌标注 380 V / △ 接法的电动机,在 380 V 电源下应采用三角形接法。( )</li><li>(单选)铭牌标 Y 接法的电动机,若误接成三角形接法,可能()。 A. 正常运转　B. 绕组电压过高烧毁　C. 转速更快　D. 无影响</li><li>(判断)电动机金属外壳必须可靠接地。( )</li><li>(单选)双电压电动机铭牌标&quot;380V/△、220V/Y&quot;,在 220 V 电源下应使用()接法。 A. 三角形　B. 星形　C. 任意　D. 串接</li><li>(判断)接线盒内三相电源线接反,电动机会反转。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。按铭牌接法接线。</li><li><strong>B</strong>。绕组承受线电压过高,可能烧毁电机。</li><li><strong>√</strong>。外壳保护接地是安全要求。</li><li><strong>B</strong>。220 V 电源用星形接法。</li><li><strong>√</strong>。相序接反导致反转。</li></ol></details>',28)])])}const b=a(n,[["render",l]]);export{c as __pageData,b as default};
